/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const passValue = event.payload.value;
	return {
		propName: "certificatePassword",
		value: passValue
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.state.topicsAcl.read.length != 0 || api.state.topicsAcl.readwrite.length != 0 ) {
    return 'lock-fill';
  }

	return null;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */

/**
 * Pass in all the necessary properties that we fetched:
 * - instanceProperties state (uri of the instance)
 * - csr properties (givenName and cert endpoint)
 */
function evaluateEvent({
    api,
    event
}) {
    let certificatePassword = api.state.certificatePassword;
    if (certificatePassword === null || certificatePassword.length === 0) {
        return;
    }

    // If we don't have read and readwrite topics' acl, just pass null
    let acl = null;
    if (api.state.topicsAcl.read.length !== 0 || api.state.topicsAcl.readwrite.length !== 0) {
        acl = api.state.topicsAcl;
    }

    let certProperties = {
        instance: api.state.instanceProperties,
        csr: {
            givenName: "Customer-Kafka",
            endpoint: "SERVICENOW_HERMES"
        },
        password: api.state.certificatePassword,
        acl: acl
    };

    return {
        certificateProperties: certProperties
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let revocationPayload = JSON.parse(JSON.stringify(api.state.revocationPayload));
	revocationPayload.hasError = false;
	return {
		propName: "revocationPayload",
		value: revocationPayload
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let topicsAclConfigCopy = JSON.parse(JSON.stringify(api.state.topicsAclConfig));
	topicsAclConfigCopy.readOnlyTopics = topicsAclConfigCopy.savedReadOnlyTopics;
	topicsAclConfigCopy.readwriteTopics = topicsAclConfigCopy.savedReadwriteTopics;
	return {
		propName: "topicsAclConfig",
		value: topicsAclConfigCopy
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let topicsAclConfigCopy = JSON.parse(JSON.stringify(api.state.topicsAclConfig));
	topicsAclConfigCopy.errorMessage = null;
	return {
		propName: 'topicsAclConfig',
		value: topicsAclConfigCopy
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let topicsAclConfigCopy = JSON.parse(JSON.stringify(api.state.topicsAclConfig));
    const value = event.payload.value;
    topicsAclConfigCopy.selectionType = value;
    topicsAclConfigCopy.selectedTopics = [];
    return {
        propName: "topicsAclConfig",
        value: topicsAclConfigCopy
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let topicsAclConfigCopy = api.state.topicsAclConfig;
    let values = event.payload.value;
    let selectedTopics = values.map(element => ({
        id: element.id,
        label: element.value,
        value: element.value
    }));
    topicsAclConfigCopy.selectedTopics = selectedTopics;
    return {
        propName: "topicsConfigAcl",
        value: topicsAclConfigCopy
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let topicsAclConfigCopy = api.state.topicsAclConfig;
    let values = event.payload.value;
    let selectedNamespaces = values.map(element => ({
        id: element.id,
        label: (element.value != null) ? (element.value + '.*') : '*',
        value: (element.value != null) ? (element.value + '.*') : '*'
    }));

    topicsAclConfigCopy.selectedNamespaces = selectedNamespaces;
    return {
        propName: "topicsConfigAcl",
        value: topicsAclConfigCopy
    };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  let output = api.data && api.data.namespaces_list && api.data.namespaces_list.output || null;
  let list = output && output.data && output.data.GlideRecord_Query
  .sys_kafka_namespace._results || null;
  if (list === null) return [];
  let resultList = list.map((result) => ({id:result._row_data.uniqueValue, label:result.name.displayValue, sublabel:result.prefix.displayValue, value: result.prefix.value}));
  return resultList;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let topicsAclConfigCopy = api.state.topicsAclConfig;
    let fieldValues = event.payload.fieldValue.split(', ').map(element => element.trim());
    let selectedTopics = fieldValues.map(element => ({
        id: element,
        label: element,
        value: element
    }));
    topicsAclConfigCopy.selectedTopics = selectedTopics;
    return {
        propName: "topicsConfigAcl",
        value: topicsAclConfigCopy
    };
}

