/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let revocationPayloadCopy = JSON.parse(JSON.stringify(api.state.revocationPayload));
	const certs = event.payload.selectedRecords;
	revocationPayloadCopy.certs = certs;
	return {
		propName: 'revocationPayload',
		value: revocationPayloadCopy
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const uri = api.state.instanceProperties.uri;
	const table = event.payload.table;
	const sysId = event.payload.sys_id;
	return {
		route: null,
		fields: null,
		params: null,
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: {url: `${table}.do?sys_id=${sysId}`},
		navigationOptions: null
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let copyPayload = JSON.parse(JSON.stringify(api.state.revocationPayload));
	const selectedReason = event.payload.value;
	copyPayload.reason = selectedReason;

	return {
		propName: 'revocationPayload',
		value: copyPayload
	};
}

